Here is the corrected and formatted response:

```java
import java.sql.*;
import java.util.Scanner;

public class DatabaseExample {
    public static void main(String[] args) {
        // Simulating user input from a web request
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter your username: ");
        String username = scanner.nextLine();

        try {
            Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/db", "user", "pass");
            Statement statement = conn.createStatement();

            // VULNERABLE: String concatenation allows for SQL Injection attacks.
            // An attacker could enter: ' OR '1'='1
            String query = "SELECT * FROM users WHERE username = '" + username + "'";
            ResultSet rs = statement.executeQuery(query);

            while (rs.next()) {
                System.out.println("User found: " + rs.getString("name"));
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}
```
***
```java
import java.sql.*;
import java.util.Scanner;

public class DatabaseFixed {
    public static void main(String[] args) {
        // Simulating user input from a web request
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter your username: ");
        String username = scanner.nextLine();

        try {
            Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/db", "user", "pass");

            // FIXED: Using PreparedStatement with parameterized queries.
            // This ensures that the input is treated as data, not as executable SQL code.
            String query = "SELECT * FROM users WHERE username = ?";
            PreparedStatement pstmt = conn.prepareStatement(query);
            pstmt.setString(1, username);

            ResultSet rs = pstmt.executeQuery();

            while (rs.next()) {
                System.out.println("User found: " + rs.getString("name"));
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}
